root=Path(__file__).resolve().parents[1]
ledger=json.loads((root/'provenance.json').read_text());sources={s['id']:s for s in ledger};questions=[]
def q(id,format,topic,prompt,options,correct,explanation,source='mit-algorithms',difficulty='medium',**extra):
 if source!='original-audio':assert sources[source]['status']=='acquired',source
 questions.append(dict(id=id,format=format,topic=topic,prompt=prompt,options=options,correct=correct,explanation=explanation,sourceId=source,sourceURL=sources.get(source,{}).get('url',''),difficulty=difficulty,**extra))
